; mandelbrot.asm - generated by gen_mandelbrot.py, do not edit by hand
; Placard CPU: the Mandelbrot set drawn in 1, 2, 4 and 8 bpp in turn,
; 32 iterations, 8 fraction bits.  See gen_mandelbrot.py for the method
; and memory map.
;     repeats forever, about 5 s pause after each mode
;
;     python3 placard_sim.py mandelbrot.asm --run --max-steps 2000000000 --png m.png
;
; Date: 10/15/2026

#include "placard.asm"

#addr 0x0000
reset:
    ld   main >> 8, y
    jmp  main

#addr 0x0100
main:
    ; ---- pass 0: 1 bpp ----
    ld   0x00, ac
    ld   ac, [0x37]
    ld   ret_1, ac
    ld   ac, [0x2C]
    ld   ret_1 >> 8, ac
    ld   ac, [0x2D]
    ld   pass0 >> 8, y
    jmp  pass0
ret_1:
    ld   ret_2, ac
    ld   ac, [0x2C]
    ld   ret_2 >> 8, ac
    ld   ac, [0x2D]
    ld   delay >> 8, y
    jmp  delay
ret_2:
    ; ---- pass 1: 2 bpp ----
    ld   0x01, ac
    ld   ac, [0x37]
    ld   ret_3, ac
    ld   ac, [0x2C]
    ld   ret_3 >> 8, ac
    ld   ac, [0x2D]
    ld   pass1 >> 8, y
    jmp  pass1
ret_3:
    ld   ret_4, ac
    ld   ac, [0x2C]
    ld   ret_4 >> 8, ac
    ld   ac, [0x2D]
    ld   delay >> 8, y
    jmp  delay
ret_4:
    ; ---- pass 2: 4 bpp ----
    ld   0x02, ac
    ld   ac, [0x37]
    ld   ret_5, ac
    ld   ac, [0x2C]
    ld   ret_5 >> 8, ac
    ld   ac, [0x2D]
    ld   pass2 >> 8, y
    jmp  pass2
ret_5:
    ld   ret_6, ac
    ld   ac, [0x2C]
    ld   ret_6 >> 8, ac
    ld   ac, [0x2D]
    ld   delay >> 8, y
    jmp  delay
ret_6:
    ; ---- pass 3: 8 bpp ----
    ld   0x03, ac
    ld   ac, [0x37]
    ld   ret_7, ac
    ld   ac, [0x2C]
    ld   ret_7 >> 8, ac
    ld   ac, [0x2D]
    ld   pass3 >> 8, y
    jmp  pass3
ret_7:
    ld   ret_8, ac
    ld   ac, [0x2C]
    ld   ret_8 >> 8, ac
    ld   ac, [0x2D]
    ld   delay >> 8, y
    jmp  delay
ret_8:
    ld   main >> 8, y
    jmp  main

#addr 0x0200
clear:
    ; video RAM 6000-FFFF = 0, then mode byte = [mode] for rows 6020-61FF
    ld   0x60, ac
    ld   ac, [0x38]
clr_pg:
    ld   [0x38], y
    clr  x
clr_b:
    ld   0x00, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    bne  clr_b
    ld   [0x38], ac
    inc
    ld   ac, [0x38]
    bne  clr_pg
    ld   0x60, y
    ld   0x20, x
mode0:
    ld   [0x37], ac
    ld   ac, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    bne  mode0
    ld   0x61, y
mode1:
    ld   [0x37], ac
    ld   ac, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    bne  mode1
    ld   [0x2D], y
    jmp  [0x2C]

#addr 0x0300
delay:
    ; about 5 s at 25.175 MHz, less the video stalls
    ld   0xC1, ac
    ld   ac, [0x3A]
dly3:
    ld   0x00, ac
    ld   ac, [0x39]
dly2:
    clr  ac
dly1:
    nop
    dec
    bne  dly1
    ld   [0x39], ac
    dec
    ld   ac, [0x39]
    bne  dly2
    ld   [0x3A], ac
    dec
    ld   ac, [0x3A]
    bne  dly3
    ld   [0x2D], y
    jmp  [0x2C]

#addr 0x0400
pass0:
    ; 1 bpp: 8 points per byte, 1 x 1 pixels per point
    ld   [0x2C], ac
    ld   ac, [0x3B]
    ld   [0x2D], ac
    ld   ac, [0x3C]
    ld   ret_9, ac
    ld   ac, [0x2C]
    ld   ret_9 >> 8, ac
    ld   ac, [0x2D]
    ld   clear >> 8, y
    jmp  clear
ret_9:
    ld   0x00, ac
    ld   ac, [0x2B]
    ld   0x62, ac
    ld   ac, [0x35]
    ; cx = -2.0 = -512 = (hi -4, lo 0)
    ld   0xFC, ac
    ld   ac, [0x2F]
    ld   0x00, ac
    ld   ac, [0x2E]
    ld   0x4F, ac
    ld   ac, [0x36]
col0:
    ld   [0x35], ac
    ld   ac, [0x34]
    ld   0x20, ac
    ld   ac, [0x33]
    ; cy = -240/256 = (hi -2, lo 16)
    ld   0xFE, ac
    ld   ac, [0x29]
    ld   0x10, ac
    ld   ac, [0x28]
row0:
    ld   [0x2E], ac
    ld   ac, [0x26]
    ld   [0x2F], ac
    ld   ac, [0x27]
    ld   0x00, ac
    ld   ac, [0x30]
    ld   0x08, ac
    ld   ac, [0x32]
pt0:
    ld   ret_10, ac
    ld   ac, [0x2C]
    ld   ret_10 >> 8, ac
    ld   ac, [0x2D]
    ld   kernel >> 8, y
    jmp  kernel
ret_10:
    ld   ac, [0x31]
    ld   [0x30], ac
    shr  ac
    or   [0x31], ac
    ld   ac, [0x30]
    ; next point: cx lo is a multiple of 8 plus < 8, never carries
    ld   [0x26], ac
    add  1, ac
    ld   ac, [0x26]
    ld   [0x32], ac
    dec
    ld   ac, [0x32]
    bne  pt0
    ; write the byte to 1 screen row(s)
    ld   [0x30], ac
    ld   [0x33], x
    ld   [0x34], y
    ld   ac, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    ld   ac, [0x33]
    bne  nw0
    ld   [0x34], ac
    inc
    ld   ac, [0x34]
nw0:
    ; cy += 1/256
    ld   [0x28], ac
    add  1, ac
    bge  cyok0
    and  0x7F, ac
    ld   ac, [0x28]
    ld   [0x29], ac
    inc
    ld   ac, [0x29]
    bra  cyd0
cyok0:
    ld   ac, [0x28]
cyd0:
    ; column done after 480 rows: rowy = vpage + 2
    ld   [0x34], ac
    sub  [0x35], ac
    sub  2, ac
    beq  cdone0
    ld   row0 >> 8, y
    jmp  row0
cdone0:
    ; next byte column: cx0 += 8/256, video page += 2
    ld   [0x2E], ac
    add  8, ac
    bge  cxok0
    and  0x7F, ac
    ld   ac, [0x2E]
    ld   [0x2F], ac
    inc
    ld   ac, [0x2F]
    bra  cxd0
cxok0:
    ld   ac, [0x2E]
cxd0:
    ld   [0x35], ac
    add  2, ac
    ld   ac, [0x35]
    ld   [0x36], ac
    dec
    ld   ac, [0x36]
    beq  pdone0
    ld   col0 >> 8, y
    jmp  col0
pdone0:
    ld   [0x3C], y
    jmp  [0x3B]

#addr 0x0500
