    ld   [0x30], ac
    ld   ac, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    ld   [0x30], ac
    ld   ac, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    ld   [0x30], ac
    ld   ac, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    ld   ac, [0x33]
    bne  nw2
    ld   [0x34], ac
