#addr 0x0800
kernel:
    ; in: cx, cy, coff.  out: AC = color for this mode.  returns to [reth, ret]
    clr  ac
    ld   ac, [0x10]
    ld   ac, [0x11]
    ld   ac, [0x13]
    ld   ac, [0x14]
    ld   ac, [0x12]
    ld   ac, [0x15]
    ld   0x20, ac
    ld   ac, [0x2A]
iter:
    ; x*x, y*y
    ld   [0x10], x
    ld   [0x11], ac
    add  0x20, y
    ld   [y,x], ac
    ld   ac, [0x16]
    ld   [0x11], ac
    add  0x28, y
    ld   [y,x], ac
    ld   ac, [0x17]
    ld   [0x13], x
    ld   [0x14], ac
    add  0x20, y
    ld   [y,x], ac
    ld   ac, [0x18]
    ld   [0x14], ac
    add  0x28, y
    ld   [y,x], ac
    ld   ac, [0x19]
    ; t = x*x + y*y, escape if t >= 4.0 (hi >= 8)
    ld   [0x16], ac
    add  [0x18], ac
    bge  nc_17
    and  0x7F, ac
    ld   ac, [0x1A]
    ld   [0x17], ac
    add  [0x19], ac
    inc
    bra  ad_18
nc_17:
    ld   ac, [0x1A]
    ld   [0x17], ac
    add  [0x19], ac
ad_18:
    ld   ac, [0x1B]
    sub  8, ac
    bge  escape
    ; x' = x*x - y*y + cx
    ld   [0x16], ac
    sub  [0x18], ac
    bge  nb_19
    and  0x7F, ac
    ld   ac, [0x1C]
    ld   [0x17], ac
    sub  [0x19], ac
    dec
    bra  sd_20
nb_19:
    ld   ac, [0x1C]
    ld   [0x17], ac
    sub  [0x19], ac
sd_20:
    ld   ac, [0x1D]
    ld   [0x1C], ac
    add  [0x26], ac
    bge  nc_21
    and  0x7F, ac
    ld   ac, [0x1E]
    ld   [0x1D], ac
    add  [0x27], ac
    inc
    bra  ad_22
nc_21:
    ld   ac, [0x1E]
    ld   [0x1D], ac
    add  [0x27], ac
ad_22:
    ld   ac, [0x1F]
    ld   kernel2 >> 8, y
    jmp  kernel2
escape:
    ; color from the iterations left (0 = never escaped)
    ld   [0x2A], ac
    add  [0x2B], ac
    ld   ac, x
    ld   0x10, y
    ld   [y,x], ac
    ld   [0x2D], y
    jmp  [0x2C]

#addr 0x0900
kernel2:
    ; s = |x + y|
    ld   [0x12], ac
    xor  [0x15], ac
    bne  sdiff
    ld   [0x10], ac
    add  [0x13], ac
    bge  nc_23
    and  0x7F, ac
    ld   ac, [0x22]
    ld   [0x11], ac
    add  [0x14], ac
    inc
    bra  ad_24
nc_23:
    ld   ac, [0x22]
    ld   [0x11], ac
    add  [0x14], ac
ad_24:
    ld   ac, [0x23]
    bra  sdone
sdiff:
    ld   [0x10], ac
    sub  [0x13], ac
    bge  nb_25
    and  0x7F, ac
    ld   ac, [0x22]
    ld   [0x11], ac
    sub  [0x14], ac
    dec
    bra  sd_26
nb_25:
    ld   ac, [0x22]
    ld   [0x11], ac
    sub  [0x14], ac
sd_26:
    ld   ac, [0x23]
    bge  sdone
    ld   [0x13], ac
    sub  [0x10], ac
    bge  nb_27
    and  0x7F, ac
    ld   ac, [0x22]
    ld   [0x14], ac
    sub  [0x11], ac
    dec
    bra  sd_28
nb_27:
    ld   ac, [0x22]
    ld   [0x14], ac
    sub  [0x11], ac
sd_28:
    ld   ac, [0x23]
sdone:
    ld   [0x22], x
    ld   [0x23], ac
    add  0x20, y
    ld   [y,x], ac
    ld   ac, [0x24]
    ld   [0x23], ac
    add  0x28, y
    ld   [y,x], ac
    ld   ac, [0x25]
    ; y' = s*s - t + cy  (= 2xy + cy)
    ld   [0x24], ac
    sub  [0x1A], ac
    bge  nb_29
    and  0x7F, ac
    ld   ac, [0x20]
    ld   [0x25], ac
    sub  [0x1B], ac
    dec
    bra  sd_30
nb_29:
    ld   ac, [0x20]
    ld   [0x25], ac
    sub  [0x1B], ac
sd_30:
    ld   ac, [0x21]
    ld   [0x20], ac
    add  [0x28], ac
    bge  nc_31
    and  0x7F, ac
    ld   ac, [0x20]
    ld   [0x21], ac
    add  [0x29], ac
    inc
    bra  ad_32
nc_31:
    ld   ac, [0x20]
    ld   [0x21], ac
    add  [0x29], ac
ad_32:
    ld   ac, [0x21]
    ld   kernel3 >> 8, y
    jmp  kernel3

#addr 0x0A00
kernel3:
    ; back to magnitude + sign, escape if |x'| or |y'| >= 2
    ld   [0x1F], ac
    blt  neg_33
    sub  4, ac
    bge  esc3
    ld   [0x1E], ac
    ld   ac, [0x10]
    ld   [0x1F], ac
    ld   ac, [0x11]
    clr  ac
    ld   ac, [0x12]
    bra  sm_36
neg_33:
    clr  ac                    ; magnitude = 0 - value
    sub  [0x1E], ac
    bge  nb_34
    and  0x7F, ac
    ld   ac, [0x10]
    clr  ac
    sub  [0x1F], ac
    dec
    bra  mh_35
nb_34:
    ld   ac, [0x10]
    clr  ac
    sub  [0x1F], ac
mh_35:
    ld   ac, [0x11]
    sub  4, ac
    bge  esc3
    ld   1, ac
    ld   ac, [0x12]
sm_36:
    ld   [0x21], ac
    blt  neg_37
    sub  4, ac
    bge  esc3
    ld   [0x20], ac
    ld   ac, [0x13]
    ld   [0x21], ac
    ld   ac, [0x14]
    clr  ac
    ld   ac, [0x15]
    bra  sm_40
neg_37:
    clr  ac                    ; magnitude = 0 - value
    sub  [0x20], ac
    bge  nb_38
    and  0x7F, ac
    ld   ac, [0x13]
    clr  ac
    sub  [0x21], ac
    dec
    bra  mh_39
nb_38:
    ld   ac, [0x13]
    clr  ac
    sub  [0x21], ac
mh_39:
    ld   ac, [0x14]
    sub  4, ac
    bge  esc3
    ld   1, ac
    ld   ac, [0x15]
sm_40:
    ld   [0x2A], ac
    dec
    ld   ac, [0x2A]
    beq  esc3                 ; never escaped: it = 0 -> black
    ld   iter >> 8, y
    jmp  iter
esc3:
    ld   escape >> 8, y
    jmp  escape

